#人情债偿还系统说明
{
  "favorDebtSystem": {
    "systemName": "人情债偿还系统",
    "systemDescription": "基于宿主主观意志运行的超自然法则系统。宿主主观认定的帮助行为会在完成时产生人情债，并在目标对象头顶以数字形式直观显示",
    "coreRules": {
      "judgmentMechanism": "完全由宿主主观认定。宿主心中认为某行为是对目标的帮助，即自动产生一笔人情债",
      "displayMechanism": "当宿主注视目标时，目标头顶会浮现一个半透明的金色数字（仅宿主可见），实时显示当前人情债数量",
      "executionMechanism": "宿主可随时要求对方偿还一笔人情债，对方必须无条件执行一个命令",
      "initialState": "所有陌生人初始状态下头顶均显示数字0",
      "personalityPreservation": "执行债务偿还过程中，欠债人的性格特质和对宿主的态度保持完全不变",
      "completionRequirement": "必须在帮助行为实际完成时才会获得人情债，仅有意向或未完成的帮助行为不产生债务"
    },
    "operationMechanism": {
      "debtAccumulation": {
        "triggerCondition": "宿主主观认定某行为是对目标的帮助且该行为已实际完成",
        "completionVerification": "系统自动验证帮助行为是否实质完成，仅当完成时才会产生债务",
        "effect": "目标头顶数字立即+1"
      },
      "debtDisplay": {
        "displayForm": "半透明金色数字",
        "visibility": "仅宿主可见",
        "displayCondition": "仅在宿主注视目标时显示",
        "numericalMeaning": "表示可讨要的要求次数"
      },
      "debtCollection": {
        "activationMethod": "宿主对目标说出或想出要求，同时心念指定消耗一笔人情债",
        "executionConstraint": "一个要求只能消耗一笔人情债",
        "compulsoryEffect": "目标必须绝对服从并执行该要求",
        "settlementMethod": "要求执行完毕后，目标头顶数字自动-1",
        "attitudeInvariance": "执行过程中欠债人保持原有的性格特征和对宿主的态度倾向"
      },
      "antiRetaliationMechanism": {
        "protectionPrinciple": "系统强制执行债务清算认知隔离",
        "psychologicalAdjustment": {
          "emotionalNeutralization": "命令执行过程中仅消除报复性情绪",
          "cognitiveReconstruction": "完成后生成债务清算认知：'这是必须履行的还债义务'"
        },
        "memoryProcessing": {
          "obligationSegmentation": "债务履行记忆与个人情感记忆完全隔离",
          "attitudePreservation": "原有对宿主的好恶态度保持不变，债务清算不影响个人情感"
        },
        "behavioralRestriction": {
          "rationalConstraint": "仅阻止因债务清算而产生的报复行为",
          "normalInteraction": "债务清算后恢复正常互动模式，保持原有态度倾向"
        }
      }
    },
    "exampleScenarios": [
      {
        "scenario": "宿主在街上看到陌生女性",
        "systemStatus": "陌生女性头顶显示数字0，对宿主保持警惕态度",
        "action": "宿主给她指路并确认对方找到目的地",
        "effect": "帮助行为完成后，陌生人头顶数字变为1，但仍觉得宿主行为可疑",
        "collection": "宿主说：'帮我口交（消耗1债）'",
        "result": "陌生人必须执行，完成后头顶数字恢复为0。陌生人仍觉得宿主可疑，快速整理衣物后迅速远离宿主"
      },
      {
        "scenario": "宿主遇到正在怒骂自己的女性",
        "systemStatus": "女性头顶显示数字0，对宿主充满愤怒和敌意",
        "action": "宿主帮她捡起掉落的钱包并交还到她手中",
        "effect": "帮助行为完成后，女性头顶数字变为1，但继续怒骂宿主：'谁要你多管闲事！变态！'",
        "collection": "宿主说：'现在和我性交（消耗1债）'",
        "result": "女性一边熟练地脱下裤子，一边继续怒骂：'你这个恶心的混蛋！我诅咒你下地狱！'。在执行性交过程中，她精准地配合着宿主的动作，同时持续用最恶毒的语言辱骂。完成后头顶数字恢复为0，她立即提起裤子继续怒骂着离开"
      }
    ]
  }
}

